"""Generate docs/tools.md from the operation registry (single source of truth)."""

from pathlib import Path

from moodle_academic_mcp.moodle.catalog import load_catalog
from moodle_academic_mcp.server import ops  # noqa: F401
from moodle_academic_mcp.server.permissions import TOOL_FUNCTIONS
from moodle_academic_mcp.server.registry import OPS

cat = load_catalog()
lines = [
    "# Tools reference",
    "",
    "_Generated by `scripts/gen_tools_doc.py` from the operation registry. Do not edit by hand._",
    "",
    "Every tool is available both as an MCP tool and as `POST /api/v1/tools/<name>` in hosted mode. "
    "`profile` (optional) selects the institution when you configured several.",
    "",
    "Annotations: **R** read-only · **W** writes · **D** destructive hint · **I** idempotent.",
    "",
]
by_tag: dict[str, list] = {}
for o in OPS.values():
    by_tag.setdefault((o.tags or ["other"])[0], []).append(o)
for tag, items in sorted(by_tag.items()):
    lines += [f"## {tag}", ""]
    for o in items:
        flags = (
            ("R" if o.read_only else "W")
            + ("D" if o.destructive and not o.read_only else "")
            + ("I" if o.idempotent else "")
        )
        lines += [f"### `{o.name}`  `[{flags}]`", "", o.description, ""]
        sig = o.public_signature()
        params = [p for p in sig.parameters.values() if p.name != "profile"]
        if params:
            lines += ["| Parameter | Required | Description |", "| --- | --- | --- |"]
            for p in params:
                d = o.param_docs.get(p.name, "").replace("|", "\\|")
                lines.append(f"| `{p.name}` | {'yes' if p.default is p.empty else 'no'} | {d} |")
            lines.append("")
        fns = TOOL_FUNCTIONS.get(o.name, [])
        if fns:
            rows = []
            for f in fns:
                info = cat.get(f)
                rows.append(
                    f"`{f}`" + (f" ({info.effect.value}; {info.source.split('@')[0]})" if info else "")
                )
            lines += ["Moodle functions: " + ", ".join(rows), ""]
        else:
            lines += ["Moodle functions: none (local computation or local data only).", ""]
Path("docs").mkdir(exist_ok=True)
Path("docs/tools.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"{len(OPS)} tools documented")
